class Solution:
    def nextArrangement(self, values: List[int]) -> List[int]:
        count = [0] * 101
        for v in values:
            count[v] += 1
        buf = []
        def build():
            if len(buf) == len(values):
                return list(buf) if buf > values else None
            for v in range(101):
                if count[v]:
                    count[v] -= 1
                    buf.append(v)
                    found = build()
                    buf.pop()
                    count[v] += 1
                    if found:
                        return found
            return None
        return build() or sorted(values)

