class Solution {
    private int[] count = new int[101], buf, target;

    public int[] nextArrangement(int[] values) {
        target = values;
        buf = new int[values.length];
        for (int v : values) count[v]++;
        if (build(0)) return buf;
        int[] out = values.clone();
        Arrays.sort(out);
        return out;
    }

    private boolean build(int pos) {
        if (pos == buf.length) return Arrays.compare(buf, target) > 0;
        for (int v = 0; v <= 100; v++) {
            if (count[v] == 0) continue;
            count[v]--;
            buf[pos] = v;
            boolean found = build(pos + 1);
            count[v]++;
            if (found) return true;
        }
        return false;
    }
}

